/// Values were derived separately from the stated light, base colour and
/// E/pi environment inputs.  They deliberately are not generated by the
/// workload's oracle: if its direct/indirect partition or binary16 boundary
/// changes, these fixed controls fail.
const EXPECTED: [(&str, [u8; 4], [u8; 4]); 5] = [
    ("ao-one-environment", [31, 49, 69, 255], [32, 49, 69, 255]),
    ("ao-zero-environment", [25, 34, 44, 255], [25, 34, 44, 255]),
    (
        "emissive-no-environment",
        [153, 98, 76, 255],
        [153, 98, 76, 255],
    ),
    (
        "emissive-ao-zero-environment",
        [153, 98, 76, 255],
        [153, 98, 76, 255],
    ),
    (
        "combined-nonsaturated",
        [159, 113, 101, 255],
        [160, 113, 101, 255],
    ),
];

#[test]
fn non_saturated_effect_controls_match_independent_numeric_contract() {
    let actual = crate::m1_surface_effects::oracle_codes_for_test();
    assert_eq!(actual.len(), EXPECTED.len());
    for ((actual_name, forward, deferred), (expected_name, expected_forward, expected_deferred)) in
        actual.iter().zip(EXPECTED)
    {
        assert_eq!(actual_name, &expected_name);
        assert_eq!(*forward, expected_forward, "Forward {actual_name}");
        assert_eq!(*deferred, expected_deferred, "Deferred {actual_name}");
        assert!(forward[..3].iter().all(|channel| *channel < 255));
        assert!(deferred[..3].iter().all(|channel| *channel < 255));
    }

    let by_name = |name| actual.iter().find(|(case, _, _)| *case == name).unwrap();
    let (_, ao_one, _) = by_name("ao-one-environment");
    let (_, ao_zero, _) = by_name("ao-zero-environment");
    let (_, emissive_no_environment, _) = by_name("emissive-no-environment");
    let (_, emissive_ao_zero, _) = by_name("emissive-ao-zero-environment");
    let (_, combined, _) = by_name("combined-nonsaturated");

    // Alpha changes indirect irradiance only: the direct-only base is visible
    // in both AO controls and their delta is nonzero.
    assert_ne!(ao_one, ao_zero);
    // With AO zero, adding an environment cannot alter direct or emissive.
    assert_eq!(emissive_no_environment, emissive_ao_zero);
    // Restoring AO changes only the environment contribution and remains
    // observable before final UNORM saturation.
    assert_ne!(combined, emissive_ao_zero);
}

#[test]
fn effects_workload_declares_real_rgba16float_attachment() {
    let input = crate::m1_surface_effects::input_evidence_for_test();
    assert!(input.contains("\"deferredEffectsAttachment\":{\"format\":\"Rgba16Float\""));
    assert!(input.contains("\"rgb\":\"emissive\""));
    assert!(input.contains("\"a\":\"occlusion\""));
}
